import { backendClient } from './client'

export const backendMarketplaceService = {
  async purchaseApp(tenantId: string, appId: string): Promise<{ transactionId: string }> {
    return backendClient.fetch('/marketplace/purchase', {
      method: 'POST',
      body: JSON.stringify({ tenantId, appId }),
    })
  },

  async useTemplate(projectId: string, templateId: string): Promise<{ projectId: string }> {
    return backendClient.fetch('/marketplace/template/use', {
      method: 'POST',
      body: JSON.stringify({ projectId, templateId }),
    })
  },
}
